    assert.ok(taskList.indexOf('First task') < taskList.indexOf('&lt;b&gt;Second'));
    assert.match(taskList, /aria-label="Complete First task"/);
    assert.match(taskList, /&lt;b&gt;Second &amp; &quot;task&quot;&lt;\/b&gt;/);
