content.text:
import http from 'node:http';
import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';
import { renderProjects, renderProject, renderNotFound } from './views.js';

const databasePath = process.env.DB_PATH || 'data/workboard.sqlite';
mkdirSync(dirname(databasePath), { recursive: true });
const database = new DatabaseSync(databasePath);
database.exec(`
  PRAGMA foreign_keys = ON;
  CREATE TABLE IF NOT EXISTS projects (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL CHECK(length(trim(name)) > 0)
  );
  CREATE TABLE IF NOT EXISTS tasks (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    project_id INTEGER NOT NULL REFERENCES projects(id),
    title TEXT NOT NULL CHECK(length(trim(title)) > 0),
    completed INTEGER NOT NULL DEFAULT 0 CHECK(completed IN (0, 1))
  );
  CREATE INDEX IF NOT EXISTS tasks_project_id ON tasks(project_id);
`);
const listProjects = database.prepare('SELECT id, name FROM projects ORDER BY id');
const getProject = database.prepare('SELECT id, name FROM projects WHERE id = ?');
const createProject = database.prepare('INSERT INTO projects (name) VALUES (?)');
const listTasks = database.prepare('SELECT id, title, completed FROM tasks WHERE project_id = ? ORDER BY id');
const createTask = database.prepare('INSERT INTO tasks (project_id, title) VALUES (?, ?)');
const updateTask = database.prepare('UPDATE tasks SET completed = ? WHERE id = ? AND project_id = ?');

function taskFilter(value) {
  return ['all', 'open', 'completed'].includes(value) ? value : 'all';
}

function projectPage(project, filter, error = '') {
  const tasks = listTasks.all(project.id).filter((task) => (
    filter === 'all' || Boolean(task.completed) === (filter === 'completed')
  ));
  return renderProject(project, tasks, filter, error);
}

function sendHtml(response, status, html) {
  response.writeHead(status, { 'Content-Type': 'text/html; charset=utf-8' });
  response.end(html);
}

async function readForm(request) {
  const chunks = [];
  let size = 0;
  for await (const chunk of request) {
    size += chunk.length;
    if (size > 16_384) {
      const error = new Error('Request body is too large');
      error.status = 413;
      throw error;
    }
    chunks.push(chunk);
  }
  return new URLSearchParams(Buffer.concat(chunks).toString('utf8'));
}

const server = http.createServer(async (request, response) => {
  try {
    const url = new URL(request.url, 'http://localhost');
    const path = url.pathname;
    if (request.method === 'GET' && path === '/health') {
      response.writeHead(200, { 'Content-Type': 'application/json' });
      response.end(JSON.stringify({ status: 'ok' }));
    } else if (request.method === 'GET' && path === '/') {
      sendHtml(response, 200, renderProjects(listProjects.all()));
    } else if (request.method === 'POST' && path === '/projects') {
      const form = await readForm(request);
      const name = (form.get('name') || '').trim();
      if (!name) {
        sendHtml(response, 400, renderProjects(listProjects.all(), 'Project name is required'));
        return;
      }
      createProject.run(name);
      response.writeHead(303, { Location: '/' });
      response.end();
    } else if (request.method === 'GET' && /^\/projects\/[1-9]\d*$/.test(path)) {
      const id = Number(path.split('/')[2]);
      const project = Number.isSafeInteger(id) ? getProject.get(id) : undefined;
      sendHtml(response, project ? 200 : 404, project ? projectPage(project, taskFilter(url.searchParams.get('filter'))) : renderNotFound());
    } else if (request.method === 'POST' && /^\/projects\/[1-9]\d*\/tasks(?:\/[1-9]\d*)?$/.test(path)) {
      const [, , projectId, , taskId] = path.split('/');
      const id = Number(projectId);
      const project = Number.isSafeInteger(id) ? getProject.get(id) : undefined;
      if (!project) {
        sendHtml(response, 404, renderNotFound());
        return;
      }
      const form = await readForm(request);
      const filter = taskFilter(form.get('filter'));
      if (taskId) {
        const task = Number(taskId);
        if (!Number.isSafeInteger(task) || updateTask.run(form.get('completed') === 'on' ? 1 : 0, task, id).changes === 0) {
          sendHtml(response, 404, renderNotFound());
          return;
        }
      } else {
        const title = (form.get('title') || '').trim();
        if (!title) {
          sendHtml(response, 400, projectPage(project, filter, 'Task title is required'));
          return;
        }
        createTask.run(id, title);
      }
      response.writeHead(303, { Location: `/projects/${id}?filter=${filter}` });
      response.end();
    } else {
      sendHtml(response, 404, renderNotFound());
    }
  } catch (error) {
    console.error(error);
    if (!response.headersSent) {
      response.writeHead(error.status || 500, { 'Content-Type': 'text/plain; charset=utf-8' });
    }
    response.end(error.status === 413 ? 'Request body is too large' : 'Internal server error');
  }
});

server.listen(Number(process.env.PORT || 8080), '0.0.0.0');
for (const signal of ['SIGINT', 'SIGTERM']) {
  process.on(signal, () => {
    server.close(() => {
      database.close();
      process.exit(0);
    });
  });
}

function escapeHtml(value) {
  return String(value).replace(/[&<>"']/g, (character) => ({
    '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;',
  })[character]);
}

function page(title, content) {
  return `<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>${escapeHtml(title)} — Workboard</title>
  <style>
    :root { font-family: system-ui, sans-serif; color: #192b3b; background: #f3f6fa; }
    body { margin: 0; }
    main { max-width: 720px; margin: 3rem auto; padding: 2rem; background: white; border-radius: 12px; }
    h1 { margin-top: 0; overflow-wrap: anywhere; }
    label { display: block; font-weight: 600; margin-bottom: .5rem; }
    input { box-sizing: border-box; width: 100%; padding: .75rem; border: 1px solid #65788a; border-radius: 5px; font: inherit; }
    button { border: 0; border-radius: 5px; padding: .7rem 1rem; background: #245bc2; color: white; font: inherit; cursor: pointer; }
    button:hover { background: #194597; }
    select { font: inherit; padding: .5rem; }
    .task-filter { margin-top: 1.5rem; }
    .task { display: flex; align-items: center; gap: .75rem; border-top: 1px solid #d6dee7; padding: 1rem 0; overflow-wrap: anywhere; }
    .task input { width: auto; }
    .task form { display: flex; align-items: center; }
    input:focus-visible, select:focus-visible, button:focus-visible { outline: 3px solid #dd9800; outline-offset: 3px; }
    .create button { margin-top: .75rem; }
    .projects { margin-top: 2rem; }
    .project { display: flex; align-items: center; justify-content: space-between; gap: 1rem; padding: 1rem 0; border-top: 1px solid #d6dee7; }
    .project span { overflow-wrap: anywhere; min-width: 0; }
    .project form { flex-shrink: 0; }
    [role="alert"] { color: #a01717; margin: 1rem 0; }
    @media (max-width: 600px) { main { margin: 1rem; padding: 1.25rem; } }
  </style>
</head>
<body><main>${content}</main></body>
</html>`;
}

export function renderProjects(projects, error = '') {
  return page('Projects', `<h1>Workboard</h1>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form class="create" action="/projects" method="post">
      <label for="project-name">Project name</label>
      <input id="project-name" name="name" type="text">
      <button type="submit">Create project</button>
    </form>
    <section class="projects" aria-label="Projects">
      ${projects.map((project) => `<div class="project" data-testid="project-row">
        <span>${escapeHtml(project.name)}</span>
        <form action="/projects/${project.id}" method="get"><button type="submit">Open project</button></form>
      </div>`).join('')}
    </section>`);
}

export function renderProject(project, tasks = [], filter = 'all', error = '') {
  return page(project.name, `<h1>${escapeHtml(project.name)}</h1>
    <form action="/" method="get"><button type="submit">Projects</button></form>
    ${error ? `<p role="alert">${escapeHtml(error)}</p>` : ''}
    <form class="create" action="/projects/${project.id}/tasks" method="post">
      <input type="hidden" name="filter" value="${filter}">
      <label for="task-title">Task title</label>
      <input id="task-title" name="title" type="text">
      <button type="submit">Create task</button>
    </form>
    <form class="task-filter" action="/projects/${project.id}" method="get">
      <label for="task-filter">Task filter</label>
      <select id="task-filter" name="filter" onchange="this.form.requestSubmit()">
        ${[['all', 'All'], ['open', 'Open'], ['completed', 'Completed']].map(([value, label]) => `<option value="${value}"${filter === value ? ' selected' : ''}>${label}</option>`).join('')}
      </select>
    </form>
    <section aria-label="Tasks">
      ${tasks.map((task) => `<div class="task" data-testid="task-row">
        <form action="/projects/${project.id}/tasks/${task.id}" method="post">
          <input type="hidden" name="filter" value="${filter}">
          <input type="checkbox" name="completed" aria-label="Complete ${escapeHtml(task.title)}"${task.completed ? ' checked' : ''} onchange="this.form.requestSubmit()">
        </form>
        <span>${escapeHtml(task.title)}</span>
      </div>`).join('')}
    </section>`);
}

export function renderNotFound() {
  return page('Not found', '<h1>Page not found</h1><form action="/" method="get"><button type="submit">Projects</button></form>');
}

{
  "name": "workboard",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "start": "node server.js",
    "test": "node --test"
  }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { mkdtemp, rm } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { createServer } from 'node:net';
import { once } from 'node:events';

async function unusedPort() {
  const socket = createServer();
  socket.listen(0, '127.0.0.1');
  await once(socket, 'listening');
  const port = socket.address().port;
  await new Promise((resolve) => socket.close(resolve));
  return port;
}

test('projects and tasks: validation, ownership, filtering, completion and restart persistence', async () => {
  const directory = await mkdtemp(join(tmpdir(), 'workboard-test-'));
  const port = await unusedPort();
  const base = `http://127.0.0.1:${port}`;
  let child;
  let errors = '';
  async function start() {
    child = spawn(process.execPath, ['server.js'], {
      env: { ...process.env, PORT: String(port), DB_PATH: join(directory, 'projects.sqlite') },
      stdio: ['ignore', 'ignore', 'pipe'],
    });
    child.stderr.on('data', (data) => { errors += data; });
    for (let i = 0; i < 100; i++) {
      if (child.exitCode !== null) throw new Error(errors);
      try {
        const response = await fetch(`${base}/health`);
        assert.equal(response.status, 200);
        assert.deepEqual(await response.json(), { status: 'ok' });
        return;
      } catch {
        await new Promise((resolve) => setTimeout(resolve, 25));
      }
    }
    throw new Error(`Server did not start: ${errors}`);
  }
  async function stop() {
    if (child && child.exitCode === null) {
      const exited = once(child, 'exit');
      child.kill('SIGTERM');
      await exited;
    }
  }
  async function create(name) {
    return fetch(`${base}/projects`, {
      method: 'POST',
      body: new URLSearchParams({ name }),
      redirect: 'manual',
    });
  }
  try {
    await start();
    const initial = await (await fetch(base)).text();
    assert.match(initial, /<h1>Workboard<\/h1>/);
    assert.match(initial, /<label for="project-name">Project name<\/label>/);
    assert.match(initial, />Create project<\/button>/);
    assert.doesNotMatch(initial, /data-testid="project-row"/);
    for (const name of ['', '  \t\n ']) {
      const response = await create(name);
      assert.equal(response.status, 400);
      const html = await response.text();
      assert.match(html, /role="alert">Project name is required/);
      assert.doesNotMatch(html, /data-testid="project-row"/);
    }
    assert.equal((await create('  First project  ')).status, 303);
    assert.equal((await create('第二 <script> & "project"')).status, 303);
    const list = await (await fetch(base)).text();
    assert.equal((list.match(/data-testid="project-row"/g) || []).length, 2);
    assert.ok(list.indexOf('First project') < list.indexOf('第二'));
    assert.match(list, /第二 &lt;script&gt; &amp; &quot;project&quot;/);
    const routes = [...list.matchAll(/action="(\/projects\/\d+)"/g)].map((match) => match[1]);
    assert.equal(routes.length, 2);
    const detail = await (await fetch(`${base}${routes[0]}`)).text();
    assert.match(detail, /<h1>First project<\/h1>/);
    assert.match(detail, /action="\/"/);
    assert.match(detail, />Projects<\/button>/);
    await create('  ');
    assert.equal(await (await fetch(base)).text(), list);
    await stop();
    await start();
    assert.equal(await (await fetch(base)).text(), list);
    assert.equal(await (await fetch(`${base}${routes[0]}`)).text(), detail);
    assert.equal((await fetch(`${base}/projects/99999`)).status, 404);

    const projectPath = routes[0];
    async function postTask(path, fields) {
      return fetch(`${base}${path}`, {
        method: 'POST', body: new URLSearchParams(fields), redirect: 'manual',
      });
    }
    async function tasksPage(filter = 'all', path = projectPath) {
      return (await fetch(`${base}${path}?filter=${filter}`)).text();
    }
    const emptyTasks = await tasksPage();
    assert.match(emptyTasks, /<label for="task-title">Task title<\/label>/);
    assert.match(emptyTasks, />Create task<\/button>/);
    assert.match(emptyTasks, /<label for="task-filter">Task filter<\/label>/);
    assert.match(emptyTasks, /value="all" selected>All/);
    assert.match(emptyTasks, />Open<\/option>/);
    assert.match(emptyTasks, />Completed<\/option>/);
    for (const title of ['', ' \t\n ']) {
      const response = await postTask(`${projectPath}/tasks`, { title });
      assert.equal(response.status, 400);
      const html = await response.text();
      assert.match(html, /role="alert">Task title is required/);
      assert.doesNotMatch(html, /data-testid="task-row"/);
    }
    assert.equal((await postTask(`${projectPath}/tasks`, { title: '  First task  ' })).status, 303);
    assert.equal((await postTask(`${projectPath}/tasks`, { title: '<b>Second & "task"</b>' })).status, 303);
    const taskList = await tasksPage();
    assert.equal((taskList.match(/data-testid="task-row"/g) || []).length, 2);
    assert.ok(taskList.indexOf('First task') < taskList.indexOf('&lt;b&gt;Second'));
    assert.match(taskList, /aria-label="Complete First task"/);
    assert.match(taskList, /&lt;b&gt;Second &amp; &quot;task&quot;&lt;\/b&gt;/);
    assert.doesNotMatch(taskList, / checked/);
    const openTasks = await tasksPage('open');
    assert.equal((openTasks.match(/data-testid="task-row"/g) || []).length, 2);
    assert.match(openTasks, /value="open" selected>Open/);
    assert.doesNotMatch(await tasksPage('completed'), /data-testid="task-row"/);
    assert.doesNotMatch(await tasksPage('all', routes[1]), /data-testid="task-row"/);
    const taskPaths = [...taskList.matchAll(/action="(\/projects\/\d+\/tasks\/\d+)"/g)].map((match) => match[1]);
    const update = await postTask(taskPaths[0], { completed: 'on', filter: 'open' });
    assert.equal(update.status, 303);
    assert.equal(update.headers.get('location'), `${projectPath}?filter=open`);
    assert.doesNotMatch(await tasksPage('open'), /<span>First task<\/span>/);
    assert.match(await tasksPage('completed'), /<span>First task<\/span>/);
    assert.doesNotMatch(await tasksPage('completed'), /<span>&lt;b&gt;Second/);
    const wrongOwnerPath = taskPaths[0].replace(projectPath, routes[1]);
    assert.equal((await postTask(wrongOwnerPath, {})).status, 404);
    assert.equal((await postTask('/projects/99999/tasks', { title: 'No owner' })).status, 404);
    const savedTasks = await tasksPage();
    assert.match(savedTasks, /aria-label="Complete First task" checked/);
    await stop();
    await start();
    assert.equal(await tasksPage(), savedTasks);
    assert.equal(await tasksPage('unknown'), savedTasks);
    assert.equal((await postTask(taskPaths[0], {})).status, 303);
    assert.doesNotMatch(await tasksPage(), / checked/);
    assert.doesNotMatch(await tasksPage('completed'), /data-testid="task-row"/);
  } finally {
    await stop();
    await rm(directory, { recursive: true, force: true });
  }
});

